// Cold C compiler -> generated byte/word/dword I/O -> actual C UART/MMU.
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
const [vmFile,compilerFile]=process.argv.slice(2);
if(!compilerFile)throw new Error('usage: check-uart-provider.mjs VM.WASM COMPILER.WASM');
const memory=new WebAssembly.Memory({initial:8}),cm=new WebAssembly.Memory({initial:16});
const vm=(await WebAssembly.instantiate(await readFile(vmFile),{machine:{memory}})).instance.exports;
const cc=(await WebAssembly.instantiate(await readFile(compilerFile),{machine:{memory:cm}})).instance.exports;
const data=Buffer.from(memory.buffer),v=new DataView(memory.buffer),cold=new Uint8Array(cm.buffer),cv=new DataView(cm.buffer);
const dir=vm.vm_arena_min(),base=dir+4096,segments=base+1408,port=base+2048,rows=dir+512,code=base+24576,tss=base+28672;
const input=cc.compiler_arena_min(),output=input+8192,report=output+65536,entry=0x400000n;
const put=(at,x)=>v.setBigUint64(at,BigInt(x),true),slot=vm.__indirect_function_table.grow(1),cuts=new Map();
function reset(){
  data.fill(0,base);
  for(let i=0;i<6;++i){const at=dir+i*32;put(at,i<4?(i+1)*4096:(i+4)*4096);
    v.setUint32(at+8,(i+2)*4096,true);v.setUint32(at+12,3,true);v.setUint32(at+16,1,true);data.fill(0,at+20,at+32);}
  put(base+8192,0x2067);put(base+12288,0x3067);put(base+16384+16,0x4067);
  put(base+20480,0x8067);put(base+20488,0x9067);
  for(let r=0;r<16;++r)put(base+r*8,0xabcdef9887650000n+BigInt(r));
  put(base+384,entry);put(base+392,0x10443);put(base+400,0x80010011);put(base+408,0x1000);
  put(base+416,32);put(base+424,0x500);put(base+488,16);put(base+1128,42);put(port,9);
  v.setUint32(segments,2,true);v.setUint32(segments+36,0xa09b,true);
  put(segments+120,0x401000);v.setUint32(segments+128,4095,true);v.setUint32(segments+132,0x8b,true);
  v.setUint16(tss+102,104,true);
  assert.equal(vm.vm_open(base,data.length-base,4096,dir,6,6,dir+1024,9n),0);
  assert.equal(vm.vm_bind_state(base),0);assert.equal(vm.vm_bind_segments(segments),0);
}
async function compile(width,write){
  const key=width*2+write;if(cuts.has(key))return cuts.get(key);
  const bytes=[...(width===2?[0x66]:[]),write?width===1?0xee:0xef:width===1?0xec:0xed];
  cold.fill(0x90,input,input+4096);cold.set(bytes,input);
  assert.equal(cc.compiler_open_pages(input,1,entry,9n),0);assert.equal(cc.compiler_emit(entry,1,output,65536,report),0);
  const module=await WebAssembly.compile(cold.slice(output,output+Number(cv.getBigUint64(report+40,true))));
  assert.deepEqual(WebAssembly.Module.imports(module),[{module:'machine',name:'memory',kind:'memory'},
    {module:'machine',name:'io',kind:'function'}]);
  const cut=(await WebAssembly.instantiate(module,{machine:{memory,io:vm.vm_io}})).exports.cut;
  const result={cut,bytes};cuts.set(key,result);return result;
}
let comparisons=0,faults=0,refusals=0;
async function run(coordinate,width,write,value,wanted,{cpl=0,iopl=0,bit=-1,refuse=false}={}){
  const {cut,bytes}=await compile(width,write);vm.__indirect_function_table.set(slot,cut);data.set(bytes,code);
  put(base,0xabcdef9843210000n|BigInt(value));put(base+16,0xabcdef9800000000n|BigInt(coordinate));
  put(base+384,entry);put(base+392,0x10443|(iopl<<12));put(base+488,16|cpl);
  data.fill(0,tss+104,tss+4096);if(bit>=0)v.setUint16(tss+104+(coordinate>>3),1<<bit,true);
  put(rows,entry);v.setUint32(rows+8,bytes.length,true);v.setUint32(rows+12,1,true);
  v.setUint32(rows+16,slot,true);v.setUint32(rows+20,0,true);assert.equal(vm.vm_bind_execution(rows,1,9n),0);
  const expected=Buffer.from(data.subarray(base,base+1256)),hidden=Buffer.from(data.subarray(segments,segments+136));
  const denied=cpl>iopl && bit>=0 && ((1<<bit)&(((1<<width)-1)<<(coordinate&7)));
  const result=denied?107n:width!==1||refuse?6n:1n;
  assert.equal(vm.vm_run(port,9n,1),result,`port ${coordinate.toString(16)}, width ${width}, write ${write}`);
  if(result===1n){
    expected.writeBigUInt64LE(entry+BigInt(bytes.length),384);expected.writeBigUInt64LE(expected.readBigUInt64LE(1128)+1n,1128);
    expected.writeBigUInt64LE(expected.readBigUInt64LE(392)&~0x10000n,392);
    if(!write)expected.writeBigUInt64LE((expected.readBigUInt64LE(0)&~255n)|BigInt(wanted),0);
    assert.equal(vm.vm_completed(),1);assert.equal(vm.vm_source_retired(),1n);
  }else{
    assert.equal(vm.vm_completed(),0);assert.equal(vm.vm_source_retired(),0n);
    if(denied){assert.equal(v.getUint32(port+24,true),13);assert.equal(v.getUint32(port+28,true),0);++faults;}else ++refusals;
  }
  assert(data.subarray(base,base+1256).equals(expected));assert(data.subarray(segments,segments+136).equals(hidden));++comparisons;
}
// The first case is a real red against the pre-UART C provider (ENTRY_MAP).
for(const [coordinate,byte]of [[0x3f9,0],[0x3fc,8],[0x3fd,0x60],[0x3ff,0]])
for(let cpl=0;cpl<4;++cpl)for(let iopl=0;iopl<4;++iopl)
for(const width of [1,2,4])for(let bit=0;bit<16;++bit)for(const write of [0,1]){
  reset();await run(coordinate,width,write,5,byte,{cpl,iopl,bit});
}
reset();await run(0x3f8,1,1,65,0,{refuse:true});
await run(0x3fb,1,1,0x43,0,{refuse:true}); // Unowned break-line change.
await run(0x3fd,1,0,0,0x60); // Neither refusal invents a transmission.
reset();await run(0x3fc,1,1,16,0);await run(0x3fa,1,1,1,0);
for(let byte=0;byte<18;++byte)await run(0x3f8,1,1,byte,0);
await run(0x3fd,1,0,0,0x63);await run(0x3fd,1,0,0,0x61);
for(let byte=0;byte<16;++byte)await run(0x3f8,1,0,0,byte);
await run(0x3fd,1,0,0,0x60);
console.log(JSON.stringify({format:'compiled-uart-c-provider-v1',status:'pass',modules:cuts.size,comparisons,faults,refusals,
  externalTransmission:'explicitly refused, no console sink yet',linuxBoot:'not-tested',
  oracle:'complete CPU/segment plus privilege/FIFO model; independent QEMU device observations are a separate test'},null,2));
